20	public struct SessionFrame: Equatable, Sendable {
21	  public static let headerSize = 5
22	  public static let maximumPayloadSize = 1 << 20
23	
24	  public let kind: SessionFrameKind
25	  public let payload: [UInt8]
26	
27	  public init(kind: SessionFrameKind, payload: [UInt8] = []) {
28	    self.kind = kind
29	    self.payload = payload
30	  }
31	
32	  public func encoded() -> [UInt8] {
33	    var writer = SessionByteWriter()
34	    writer.writeUInt8(kind.rawValue)
35	    writer.writeUInt32(UInt32(payload.count))
36	    writer.writeRaw(payload)
37	    return writer.bytes
38	  }
39	}
