41	public struct SessionFrameDecoder: Sendable {
42	  private var buffer: [UInt8] = []
43	  private var consumed = 0
44	  private var failed = false
45	
46	  public init() {}
47	
48	  public var bufferedByteCount: Int { buffer.count - consumed }
49	
50	  public mutating func push(_ bytes: [UInt8]) {
51	    guard !failed else { return }
52	    buffer.append(contentsOf: bytes)
53	  }
54	
55	  public mutating func push(_ bytes: UnsafeBufferPointer<UInt8>) {
56	    guard !failed else { return }
57	    buffer.append(contentsOf: bytes)
58	  }
59	
60	  public mutating func next() throws -> SessionFrame? {
61	    if failed { throw SessionProtocolError.decoderFailed }
62	    guard buffer.count - consumed >= SessionFrame.headerSize else {
63	      compact()
64	      return nil
65	    }
66	    let rawKind = buffer[consumed]
67	    var length = 0
68	    for index in 1..<SessionFrame.headerSize {
69	      length = length << 8 | Int(buffer[consumed + index])
70	    }
71	    guard length <= SessionFrame.maximumPayloadSize else {
72	      failed = true
73	      throw SessionProtocolError.frameTooLarge(length)
74	    }
75	    guard buffer.count - consumed - SessionFrame.headerSize >= length else {
76	      compact()
77	      return nil
78	    }
79	    guard let kind = SessionFrameKind(rawValue: rawKind) else {
80	      failed = true
81	      throw SessionProtocolError.unknownFrameKind(rawKind)
82	    }
83	    let start = consumed + SessionFrame.headerSize
84	    let payload = Array(buffer[start..<(start + length)])
85	    consumed = start + length
86	    compact()
87	    return SessionFrame(kind: kind, payload: payload)
88	  }
89	
90	  private mutating func compact() {
91	    guard consumed > 0 else { return }
92	    if consumed == buffer.count {
93	      buffer.removeAll(keepingCapacity: true)
94	    } else if consumed >= 1 << 16 {
95	      buffer.removeFirst(consumed)
96	    } else {
97	      return
98	    }
99	    consumed = 0
100	  }
101	}
