48	  static func run(configuration: Configuration) -> Int32 {
49	    signal(SIGPIPE, SIG_IGN)
50	
51	    guard let signalPipe = SessionSignalPipe(signals: [SIGWINCH]) else {
52	      return SessionAttachExitCode.startupFailure
53	    }
54	
55	    let originalTerminal = enterRawMode()
56	    defer {
57	      if var originalTerminal {
58	        tcsetattr(STDIN_FILENO, TCSANOW, &originalTerminal)
59	      }
60	    }
61	
62	    for attempt in 0..<handshakeAttempts {
63	      switch attach(configuration: configuration, signalPipe: signalPipe) {
64	      case .finished(let status), .failed(let status):
65	        return status
66	      case .retry:
67	        if attempt + 1 < handshakeAttempts {
68	          usleep(handshakeRetryMicroseconds)
69	        }
70	      }
71	    }
72	
73	    report("could not reach the session daemon")
74	    return SessionAttachExitCode.daemonUnavailable
75	  }
76	
77	  private static func attach(configuration: Configuration, signalPipe: SessionSignalPipe) -> Outcome
78	  {
79	    let socket: Int32
80	    switch connect(socketPath: configuration.socketPath) {
81	    case .connected(let descriptor):
82	      socket = descriptor
83	    case .retry:
84	      return .retry
85	    case .failed(let status):
86	      return .failed(status)
87	    }
88	    defer { SessionIO.close(socket) }
89	    SessionIO.setNonBlocking(socket)
90	
91	    let connection = SessionConnection(descriptor: socket)
92	    connection.enqueue(SessionFrame(kind: .attach, payload: makeRequest(configuration).encoded()))
93	    return loop(connection: connection, signalPipe: signalPipe)
94	  }
95	
96	  private static func loop(connection: SessionConnection, signalPipe: SessionSignalPipe) -> Outcome
97	  {
98	    var isAttached = false
99	    while true {
100	      guard connection.flush() else { return transportOutcome(isAttached: isAttached) }
101	
102	      var descriptors = [
103	        pollfd(fd: signalPipe.readDescriptor, events: Int16(POLLIN), revents: 0),
104	        pollfd(
105	          fd: connection.descriptor,
106	          events: Int16(
107	            connection.hasPendingOutput ? Int32(POLLIN) | Int32(POLLOUT) : Int32(POLLIN)),
108	          revents: 0),
109	      ]
110	      if isAttached, connection.pendingByteCount < inputBacklogLimit {
111	        descriptors.append(pollfd(fd: STDIN_FILENO, events: Int16(POLLIN), revents: 0))
112	      }
113	
114	      let ready = poll(&descriptors, nfds_t(descriptors.count), -1)
115	      if ready < 0 {
116	        guard errno == EINTR else { return transportOutcome(isAttached: isAttached) }
117	        continue
118	      }
119	
120	      for entry in descriptors where entry.revents != 0 {
121	        if entry.fd == signalPipe.readDescriptor {
122	          signalPipe.drain()
123	          sendResize(connection)
124	        } else if entry.fd == STDIN_FILENO {
125	          guard forwardInput(connection) else { return .finished(0) }
126	        } else if let outcome = receive(connection, revents: entry.revents, isAttached: &isAttached)
127	        {
128	          _ = connection.flush()
129	          return outcome
130	        }
131	      }
132	    }
133	  }
134	
135	  private static func transportOutcome(isAttached: Bool) -> Outcome {
136	    isAttached ? .failed(SessionAttachExitCode.transportFailure) : .retry
137	  }
138	
139	  private static func forwardInput(_ connection: SessionConnection) -> Bool {
140	    switch SessionIO.read(STDIN_FILENO) {
141	    case .bytes(let bytes):
142	      connection.enqueue(SessionFrame(kind: .input, payload: bytes))
143	      return true
144	    case .wouldBlock:
145	      return true
146	    case .endOfFile, .failed:
147	      return false
148	    }
149	  }
150	
151	  private static func receive(
152	    _ connection: SessionConnection,
153	    revents: Int16,
154	    isAttached: inout Bool
155	  ) -> Outcome? {
156	    if revents & Int16(POLLOUT) != 0, !connection.flush() {
157	      return transportOutcome(isAttached: isAttached)
158	    }
159	    guard revents & Int16(POLLIN) != 0 || revents & Int16(POLLHUP) != 0 else { return nil }
160	
161	    var reachedEnd = false
162	    readLoop: while true {
163	      switch SessionIO.read(connection.descriptor) {
164	      case .bytes(let bytes):
165	        connection.decoder.push(bytes)
166	      case .wouldBlock:
167	        break readLoop
168	      case .endOfFile, .failed:
169	        reachedEnd = true
170	        break readLoop
171	      }
172	    }
173	
174	    while true {
175	      let frame: SessionFrame?
176	      do {
177	        frame = try connection.decoder.next()
178	      } catch {
179	        return .failed(SessionAttachExitCode.protocolFailure)
180	      }
181	      guard let frame else { break }
182	      switch frame.kind {
183	      case .attached:
184	        isAttached = true
185	      case .output:
186	        guard SessionIO.writeAll(STDOUT_FILENO, frame.payload) else {
187	          return transportOutcome(isAttached: isAttached)
188	        }
189	      case .exited:
190	        return .finished((try? SessionExitPayload.decode(frame.payload)) ?? 0)
191	      case .failure:
192	        report((try? SessionTextPayload.decode(frame.payload)) ?? "session failed")
193	        return .failed(SessionAttachExitCode.protocolFailure)
194	      case .attach, .input, .resize, .list, .info, .kill, .killAll, .sessions, .acknowledged:
195	        break
196	      }
197	    }
198	
199	    return reachedEnd ? transportOutcome(isAttached: isAttached) : nil
200	  }
