217	    let size = SessionWindowSizePolicy.attachSize(
218	      from: SessionPTY.windowSize(descriptor: STDIN_FILENO))
219	    let environment = SessionProcessEnvironment.current()
220	      .filter { !$0.key.hasPrefix("WORKROOM_SESSION_") }
221	      .map { SessionEnvironmentEntry(key: $0.key, value: $0.value) }
222	    return SessionAttachRequest(
223	      identifier: configuration.identifier,
224	      columns: size.columns,
225	      rows: size.rows,
226	      workingDirectory: configuration.workingDirectory,
227	      command: configuration.command,
228	      shell: configuration.shell,
