234	  private static func enterRawMode() -> termios? {
235	    var original = termios()
236	    guard tcgetattr(STDIN_FILENO, &original) == 0 else { return nil }
237	    var raw = original
238	    cfmakeraw(&raw)
239	    guard tcsetattr(STDIN_FILENO, TCSANOW, &raw) == 0 else { return nil }
240	    return original
