243	  private static func connect(socketPath: String) -> ConnectionOutcome {
244	    for _ in 0..<connectCycles {
245	      if let descriptor = SessionSocket.connect(path: socketPath) {
246	        return .connected(descriptor)
247	      }
248	      switch launchDaemon(socketPath: socketPath) {
249	      case .started, .retryableFailure:
250	        break
251	      case .fatalFailure:
252	        return .failed(SessionAttachExitCode.startupFailure)
253	      }
254	      for _ in 0..<connectAttemptsPerCycle {
255	        usleep(connectRetryMicroseconds)
256	        if let descriptor = SessionSocket.connect(path: socketPath) {
257	          return .connected(descriptor)
258	        }
259	      }
260	    }
261	    return .retry
262	  }
263	
264	  private static func launchDaemon(socketPath: String) -> DaemonLaunchOutcome {
265	    guard let binaryPath = executablePath() else {
266	      report("unable to locate the session daemon binary")
267	      return .fatalFailure
268	    }
269	    let arguments = SessionCStringArray([binaryPath, "daemon", "--socket", socketPath])
270	
271	    var fileActions: posix_spawn_file_actions_t?
272	    posix_spawn_file_actions_init(&fileActions)
273	    defer { posix_spawn_file_actions_destroy(&fileActions) }
274	    posix_spawn_file_actions_addopen(&fileActions, STDIN_FILENO, "/dev/null", O_RDWR, 0)
275	    posix_spawn_file_actions_addopen(&fileActions, STDOUT_FILENO, "/dev/null", O_RDWR, 0)
276	    posix_spawn_file_actions_addopen(
277	      &fileActions,
278	      STDERR_FILENO,
279	      socketPath + ".log",
280	      O_WRONLY | O_CREAT | O_APPEND | O_NOFOLLOW,
281	      0o600)
282	
283	    var attributes: posix_spawnattr_t?
284	    posix_spawnattr_init(&attributes)
285	    defer { posix_spawnattr_destroy(&attributes) }
286	    posix_spawnattr_setflags(&attributes, Int16(POSIX_SPAWN_SETSID))
287	
288	    var processID: pid_t = 0
289	    let result = posix_spawn(
290	      &processID, binaryPath, &fileActions, &attributes, arguments.pointer, environ)
291	    guard result != 0 else { return .started }
292	    report("could not start the session daemon (\(result))")
293	    return result == EAGAIN || result == EINTR ? .retryableFailure : .fatalFailure
294	  }
295	
296	  static func executablePath() -> String? {
297	    if let provided = SessionProcessEnvironment.value("WORKROOM_SESSION_BINARY") {
298	      return provided
299	    }
300	    var size = UInt32(PATH_MAX)
301	    var buffer = [CChar](repeating: 0, count: Int(PATH_MAX))
302	    guard _NSGetExecutablePath(&buffer, &size) == 0 else { return nil }
303	    return buffer.withUnsafeBufferPointer { pointer in
304	      guard let base = pointer.baseAddress else { return nil }
305	      return String(cString: base)
306	    }
307	  }
