129	  private static func signalSessions(_ sessionIDs: Set<pid_t>, signal: Int32) {
130	    guard let members = sessionProcessIDs(sessionIDs: sessionIDs) else {
131	      for sessionID in sessionIDs {
132	        _ = killpg(sessionID, signal)
