155	  private static func waitForSessionsExit(
156	    _ sessionIDs: Set<pid_t>,
157	    attempts: Int,
158	    repeatedSignal: Int32? = nil
159	  ) -> Set<pid_t> {
160	    var remaining = sessionIDs
161	    for _ in 0..<attempts {
162	      reap(processIDs: remaining)
163	      guard let members = sessionProcessIDs(sessionIDs: remaining) else {
164	        usleep(terminationPollMicroseconds)
165	        continue
166	      }
167	      remaining = activeSessionIDs(remaining, members: members)
168	      guard !remaining.isEmpty else { return [] }
169	      if let repeatedSignal {
170	        signalSessions(remaining, members: members, signal: repeatedSignal)
171	      }
172	      usleep(terminationPollMicroseconds)
173	    }
174	
175	    reap(processIDs: remaining)
176	    guard let members = sessionProcessIDs(sessionIDs: remaining) else { return remaining }
177	    return activeSessionIDs(remaining, members: members)
178	  }
