180	  private static func activeSessionIDs(_ sessionIDs: Set<pid_t>, members: [pid_t: [pid_t]])
181	    -> Set<pid_t>
182	  {
183	    sessionIDs.filter { processExists($0) || !(members[$0] ?? []).isEmpty }
184	  }
