186	  private static func reap(processIDs: Set<pid_t>) {
187	    for processID in processIDs {
188	      var status: Int32 = 0
189	      while waitpid(processID, &status, WNOHANG) < 0, errno == EINTR {}
190	    }
191	  }
192	
193	  private static func processExists(_ processID: pid_t) -> Bool {
194	    guard kill(processID, 0) != 0 else { return true }
195	    return errno == EPERM
196	  }
197	
198	  private static func sessionProcessIDs(sessionIDs: Set<pid_t>) -> [pid_t: [pid_t]]? {
199	    let stride = MemoryLayout<kinfo_proc>.stride
200	    for _ in 0..<3 {
201	      var name: [Int32] = [CTL_KERN, KERN_PROC, KERN_PROC_ALL]
202	      var size = 0
203	      guard sysctl(&name, 3, nil, &size, nil, 0) == 0, size > 0 else { return nil }
204	
205	      var records = [kinfo_proc](repeating: kinfo_proc(), count: size / stride + 16)
206	      size = records.count * stride
207	      if sysctl(&name, 3, &records, &size, nil, 0) != 0 {
208	        guard errno == ENOMEM else { return nil }
209	        continue
210	      }
211	
212	      var members: [pid_t: [pid_t]] = [:]
213	      for record in records.prefix(size / stride) {
214	        let processID = record.kp_proc.p_pid
215	        guard processID > 0 else { continue }
216	        let sessionID = getsid(processID)
217	        guard sessionIDs.contains(sessionID) else { continue }
218	        members[sessionID, default: []].append(processID)
219	      }
220	      return members
221	    }
222	    return nil
223	  }
